func (l *base) detectScanDest() []string {
    scanDest := []string{}
    for _, pack := range l.osPackages.Packages {
        for _, proc := range pack.AffectedProcs {
            for _, port := range proc.ListenPorts {
                if port.Address == "*" {
                    for _, ip := range l.ServerInfo.IPv4Addrs {
                        scanDest = append(scanDest, fmt.Sprintf("%s:%s", ip, port.Port))
                    }
                } else {
                    scanDest = append(scanDest, fmt.Sprintf("%s:%s", port.Address, port.Port))
                }
            }
        }
    }
    return util.UniqueStrings(scanDest)
}
